// Settings that belong to where the site is deployed, not to its code. The deploy overwrites this
// file (web/build.py) from the repository variables GOOGLE_API_KEY, which lets "Load from Google
// Drive" read files and folders shared as "Anyone with the link" (empty, the option is off), and
// DRIVE_DEFAULT_FOLDER, the link that option opens on.
window.NOR_CONFIG = {
  google: { apiKey: "" },
  drive: { defaultLink: "" },
};
"""Fetch the third-party wheels the page installs into Pyodide (packages Pyodide does not ship) into
web/vendor/, so the page never depends on PyPI at run time, and write the deployment's settings into
web/config.js from the repository variables the deploy passes in (.github/site.config's build_vars):
GOOGLE_API_KEY turns on loading from Google Drive, and DRIVE_DEFAULT_FOLDER is the link its dialog
opens on. It also writes the version history the page shows (version_history.py). The deploy runs this; so does a local preview:

  python3 web/build.py
  python3 -m http.server 8000        from the repo root, then open http://localhost:8000/web/
"""
import glob, json, os, shutil, subprocess, sys

import version_history

VENDOR = ['tifffile==2026.3.3']
HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, 'vendor')


def config_js(env):
    """The page's settings from the deploy's variables; None without a key, keeping the committed file."""
    if not env.get('GOOGLE_API_KEY'):
        return None
    settings = {'google': {'apiKey': env['GOOGLE_API_KEY']}, 'drive': {'defaultLink': env.get('DRIVE_DEFAULT_FOLDER', '')}}
    return ('// written by web/build.py from the repository variables GOOGLE_API_KEY and DRIVE_DEFAULT_FOLDER\n'
            f'window.NOR_CONFIG = {json.dumps(settings)};\n')


if __name__ == '__main__':
    shutil.rmtree(OUT, ignore_errors=True)
    subprocess.run([sys.executable, '-m', 'pip', 'download', '-q', '--no-deps', '--only-binary', ':all:', '-d', OUT, *VENDOR], check=True)
    json.dump(sorted(os.path.basename(f) for f in glob.glob(os.path.join(OUT, '*.whl'))), open(os.path.join(OUT, 'wheels.json'), 'w'))
    json.dump(version_history.history(os.path.dirname(HERE)), open(version_history.OUT, 'w'), indent=1)
    text = config_js(os.environ)
    if text:
        with open(os.path.join(HERE, 'config.js'), 'w') as f:
            f.write(text)
// The page's requests, answered by the Python session (detection/interactive.py) inside a Pyodide
// runtime that has already imported interactive and json. The worker runs it; the tests drive it
// outside a browser.
// Messages in: open {name, bytes}, detect {finder, overrides}, refilter {spec, seq}, memory.
// Messages out: progress {text}, opened {H, W, um, info, images}, detected {meta, seg}, filtered {fails, alone, seq},
// memory {used, heap, objects}.
export function bridge(py, post) {
  const say = (text) => post({ type: "progress", text });
  return function answer(m) {
    const t0 = performance.now();
    if (m.type === "open") {
      say("Reading the image and building the blue mask…");
      const path = "/tmp/" + m.name.replace(/[^\w.\-]/g, "_");
      py.FS.writeFile(path, new Uint8Array(m.bytes));
      py.globals.set("path", path);
      // the file is read once; kept, every image opened would stay in the worker's memory
      try { py.runPython("S = interactive.Session(path); H, W = S.caspr.shape; um = S.um; info = json.dumps(S.info)"); } finally { py.FS.unlink(path); }
      // a handle to a Python object keeps it alive until it is destroyed, whatever JavaScript collects
      const im = py.runPython("S.images()"), images = im.toJs(); im.destroy();
      post({ type: "opened", H: py.globals.get("H"), W: py.globals.get("W"), um: py.globals.get("um"), info: JSON.parse(py.globals.get("info")),
                images, secs: (performance.now() - t0) / 1000 }, [images.buffer]);
    } else if (m.type === "detect") {
      say("Finding candidates (the slow part)…");
      py.globals.set("finder", m.finder);
      py.globals.set("overrides", JSON.stringify(m.overrides || {}));
      const r = py.runPython("S.detect(finder, json.loads(overrides))"), s = r.get(1);
      const meta = JSON.parse(r.get(0)), seg = s.toJs(); s.destroy(); r.destroy();
      post({ type: "detected", meta, seg, secs: (performance.now() - t0) / 1000 }, [seg.buffer]);
    } else if (m.type === "refilter") {
      py.globals.set("spec", JSON.stringify(m.spec));
      const { fails, alone } = JSON.parse(py.runPython("sp = json.loads(spec); json.dumps(dict(fails=S.refilter(sp), alone=S.alone(sp)))"));
      post({ type: "filtered", fails, alone, seq: m.seq, ms: performance.now() - t0 });
    } else if (m.type === "memory") {
      // what Python holds after a collection: bytes in use by malloc, and live objects the collector
      // tracks; heap is the WebAssembly memory, which only ever grows to the high-water mark
      if (!py.globals.has("memory_use")) py.runPython(`
import ctypes, gc
class MallInfo(ctypes.Structure):
    _fields_ = [(n, ctypes.c_size_t) for n in 'arena ordblks smblks hblks hblkhd usmblks fsmblks uordblks fordblks keepcost'.split()]
libc = ctypes.CDLL(None); libc.mallinfo.restype = MallInfo
def memory_use():
    gc.collect()
    return json.dumps([libc.mallinfo().uordblks, len(gc.get_objects())])
`);
      const [used, objects] = JSON.parse(py.runPython("memory_use()"));
      post({ type: "memory", used, objects, heap: py._module.HEAPU8.byteLength });
    }
  };
}
// Runs the repo's Python finders (detection/interactive.py) under Pyodide, off the page's thread.
// Messages out while it boots: progress {text}, ready {finders, about}, error {text}; the rest are the bridge's.
// A module worker: its imports are fetched with CORS, so the service worker can cache them.
import { bridge } from "./bridge.js";

const PYODIDE = "https://cdn.jsdelivr.net/pyodide/v314.0.7/full/";

const say = (text) => postMessage({ type: "progress", text });
let py;

async function boot() {
  const t0 = performance.now();
  say("Downloading Python…");
  // Only the packages the finders import are unpacked, and each native module loads the first time
  // Python imports it: loadPackage would load every module of every package and of its dependencies
  // up front, about 100 MB more memory. A package missing here fails loudly as an ImportError.
  // They download while Python itself downloads and starts.
  const wheels = (async () => {
    const [lock, vendored] = await Promise.all([fetch(PYODIDE + "pyodide-lock.json"), fetch("vendor/wheels.json")].map(async (r) => (await r).json()));
    const list = ["numpy", "scipy", "scikit-image", "lazy-loader", "packaging", "pillow"]
      .map((n) => ({ url: PYODIDE + lock.packages[n].file_name, sha256: lock.packages[n].sha256 }))
      .concat(vendored.map((w) => ({ url: new URL("vendor/" + w, self.location.href).href })));
    expected = list.length;
    return Promise.all(list.map(fetchWheel));
  })();
  wheels.catch(() => {}); // a failed download is reported where it is awaited, after Python starts
  const { loadPyodide } = await import(PYODIDE + "pyodide.mjs");
  py = await loadPyodide({ indexURL: PYODIDE });
  stage = "Downloading packages";
  const bufs = await wheels;
  say("Installing numpy, scipy, scikit-image…");
  const site = py.runPython("import sysconfig; sysconfig.get_path('purelib')");
  for (const buf of bufs) py.unpackArchive(buf, "wheel", { extractDir: site });
  say("Loading the finders…");
  // Python modules are read straight from the repo's layout as they are imported: a new finder
  // file in detection/ ships with no list to update.
  py.globals.set("bases", py.toPy(["../detection/", "../src/"].map((b) => new URL(b, self.location.href).href)));
  py.runPython(`
import sys, os, importlib.util
from js import XMLHttpRequest

class RepoModules:
    """Imports a top-level module the runtime lacks from the site, the way it sits in the repo."""
    def find_spec(self, name, path=None, target=None):
        if path is not None or '.' in name:
            return None
        for base in bases:
            req = XMLHttpRequest.new(); req.open('GET', base + name + '.py', False); req.send()
            if req.status == 200:
                os.makedirs('/py', exist_ok=True); f = '/py/' + name + '.py'
                open(f, 'w').write(req.responseText)
                return importlib.util.spec_from_file_location(name, f)
        return None

sys.meta_path.append(RepoModules())
os.environ['NORFINDER_SRC'] = '/py'
import interactive, json
`);
  files = py.runPython("sum(os.path.getsize(os.path.join(d, f)) for top in ('/lib', '/py') for d, _, fs in os.walk(top) for f in fs)");
  const finders = JSON.parse(py.runPython("json.dumps(interactive.FINDERS)"));
  const about = JSON.parse(py.runPython("json.dumps({f: interactive.describe(f) for f in interactive.FINDERS})"));
  post({ type: "ready", finders, about, secs: (performance.now() - t0) / 1000 });
}

// the packages' download, counted for the status bar while Python starts
let stage = "Downloading Python and packages", expected = Infinity, heads = 0, sized = true, got = 0, total = 0, shown = 0;
const mb = (n) => (n / 1048576).toFixed(0);
function counted(n, size) {
  got += n; if (size !== undefined) { heads++; total += size || 0; sized &&= !!size; }
  const all = heads === expected && sized && got >= total;
  if (!n || (performance.now() - shown < 250 && !all)) return;
  shown = performance.now();
  say(`${stage}… ${mb(got)}${heads === expected && sized ? " of " + mb(total) : ""} MB`);
}

async function fetchWheel({ url, sha256 }) {
  const r = await fetch(url, { priority: "low" }); // Python itself downloads first: it starts while these finish
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  counted(0, Number(r.headers.get("content-length")));
  const parts = [], reader = r.body.getReader();
  for (let c; !(c = await reader.read()).done;) { parts.push(c.value); counted(c.value.length); }
  const buf = await new Blob(parts).arrayBuffer();
  if (sha256) {
    const got = [...new Uint8Array(await crypto.subtle.digest("SHA-256", buf))].map((b) => b.toString(16).padStart(2, "0")).join("");
    if (got !== sha256) throw new Error(`${url}: checksum mismatch`);
  }
  return buf;
}

const booted = boot().catch((e) => postMessage({ type: "error", text: String(e) }));

// every answer says how large Python's memory has grown, which never shrinks and is most of the tab's, and
// what Python's files take: the file system, Python's own library and the packages installed, is in memory
let files = 0;
const post = (m, transfer) => postMessage({ ...m, heap: py._module.HEAPU8.byteLength, files }, transfer);
let answer;
async function handle(m) {
  await booted;
  answer ||= bridge(py, post);
  answer(m);
}

let queue = Promise.resolve();
onmessage = (e) => {
  queue = queue.then(() => handle(e.data)).catch((err) => postMessage({ type: "error", text: String(err.message || err) }));
};
