118	// ---------- the user's decisions and measurements: saved per file and finder, tied to each candidate's position ----------
119	const posKey = (c) => `${Math.round(c.cx)},${Math.round(c.cy)}`;
120	const fileKey = () => st.fileName + "|" + st.meta.finder;
121	function loadMarks() {
122	  st.forced = new Map(); st.edits = new Map();
123	  const marks = readJSON(MARKS + fileKey()), edits = readJSON(EDITS + fileKey());
124	  for (const c of st.cands) {
125	    const m = marks[posKey(c)], e = edits[posKey(c)];
126	    if (m) st.forced.set(c.i, m);
127	    if (e) st.edits.set(c.i, e);
128	  }
129	}
130	function saveMap(prefix, map) {
131	  const out = {};
132	  for (const [j, v] of map) out[posKey(st.cands[j])] = v;
133	  writeJSON(prefix + fileKey(), out);
134	}
135	// the user's word on a candidate: "approve" (a NoR, with the lengths shown), "reject" (not one), or null (the filters decide)
136	function decide(i, d) {
137	  d ? st.forced.set(i, d === "approve" ? "in" : "out") : st.forced.delete(i);
138	  const e = { ...(st.edits.get(i) || {}) };
139	  d === "approve" ? (e.approved = true) : delete e.approved;
140	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
141	  saveMap(MARKS, st.forced); saveMap(EDITS, st.edits); render();
142	}
143	function edit(i, change) {
144	  const e = { ...(st.edits.get(i) || {}), ...change };
145	  for (const k of Object.keys(e)) if (e[k] == null || e[k] === false) delete e[k];
146	  Object.keys(e).length ? st.edits.set(i, e) : st.edits.delete(i);
147	  saveMap(EDITS, st.edits); drawLines(st.cands[i]); render();
148	}
