553	  const at = (y, x) => (y >= 0 && y < h && x >= 0 && x < w ? blk[y * w + x] : 0);
554	  const isv = val === 2 ? (v) => v === 2 || v === 3 : (v) => v === val;
555	  for (let y = 0; y <= h; y++) { // horizontal edges between rows y-1 and y
556	    let run = -1;
