// the buttons whose action can take a while on a slow computer; Load is held from a chosen image until it is open
for (const id of ["#find", "#switch", "#tab-pass", "#tab-fail", "#dl-cands", "#dl-summary", "#gt-export"]) slow($(id));
start();

