    def __init__(self, path):
        self.a = np.asarray(Image.open(path).convert('L'), dtype=np.uint8)

    def opened(self):
        H, W = self.a.shape
        return json.dumps(dict(H=H, W=W, um=None, info=[['Pixels', f'{W} × {H}']])), self.a.tobytes()

