598	  return e;
599	};
600	
601	function buildOverlay() {
602	  const svg = $("#overlay"); svg.innerHTML = "";
603	  svg.setAttribute("viewBox", `0 0 ${st.W} ${st.H}`);
604	  const frag = document.createDocumentFragment();
605	  for (const c of st.order) {
606	    const g = el("g", { "data-i": c.i });
607	    g.append(el("path", { class: "red", d: outline(c, c.blk, 1) }), el("path", { d: outline(c, c.blk, 2) }));
608	    c.lineEl = el("g", { class: "lines" }); g.append(c.lineEl);
609	    const t = el("text", { x: c.bb[2] + 0.5, y: c.bb[1] });
610	    const num = el("tspan", { class: "num" }), let_ = el("tspan", { class: "let", "font-weight": "bold" });
611	    num.textContent = st.numbers.get(c.i); t.append(num, let_); g.append(t);
612	    const [a, b, cc, d] = c.bb; g.append(el("rect", { class: "hit", x: a, y: b, width: cc - a, height: d - b }));
613	    c.el = g; c.text = t; frag.append(g); drawLines(c);
614	  }
615	  st.ring = el("circle", { class: "ring" }); st.ring.style.display = "none";
616	  frag.append(st.ring);
617	  svg.append(frag);
618	}
619	
620	// the measuring lines as the user left them: their own length and red lines, else the finder's
621	function linesOf(c) {
622	  if (c.added) return c.lines;
623	  if (!c.lines) return null;
624	  const e = st.edits.get(c.i) || {};
625	  return { ...c.lines, length: e.length || c.lines.length, red: e.red || c.lines.red, width: e.width || c.lines.width };
626	}
627	function drawLines(c) {
628	  const L = linesOf(c); c.lineEl.replaceChildren();
629	  if (!L) return;
630	  for (const [k, cls] of [["length", ""], ["width", ""], ["red", "r"]]) {
631	    const [[x1, y1], [x2, y2]] = L[k];
632	    c.lineEl.append(el("line", { x1, y1, x2, y2, ...(cls ? { class: cls } : {}) }));
633	  }
634	}
635	
636	// ---------- added candidates: NoRs the user added where the finder proposed none ----------
637	// Each has measuring lines the user corrects on its card, and lists first among the finalists until
638	// thumbed down. Until the user gives a verdict, a glowing circle marks it on the image.
639	function loadAdded(name) {
640	  const added = readJSON(ADDED + name, null);
641	  if (added) return added;
642	  return readJSON(MISSING + name, []).map(([x, y]) => ({ lines: typicalLines(x, y), verdict: null }));
643	}
644	function saveAdded() {
645	  writeJSON(ADDED + st.fileName, st.added);
646	  try { localStorage.removeItem(MISSING + st.fileName); } catch { /* private mode */ }
647	}
648	// level lines centred on (x, y), as long and wide as this image's finalists' medians
649	function typicalLines(x, y) {
650	  const med = (k) => { const s = stats((st.passes || []).filter((c) => !c.added).map((c) => c.m && c.m[k])); return s.n ? s.med : TYPICAL[k]; };
651	  const len = med("length"), red = Math.min(len - 2, med("red_length")), w = med("width");
652	  const level = (a) => [[x - a / 2, y], [x + a / 2, y]];
653	  return { length: level(len), red: level(red), width: [[x, y - w / 2], [x, y + w / 2]] };
654	}
655	// an added NoR as a candidate: "u1", "u2", ... in place of a finder's index
656	const isAdded = (i) => typeof i === "string";
657	function addedCand(k) {
658	  const a = st.added[k]; if (!a) return null;
659	  const L = a.lines, pts = [...L.length, ...L.red, ...L.width], [[p, q], [r, t]] = L.length;
660	  const m = { length: dist(L.length), red_length: dist(L.red), width: dist(L.width) };
661	  m.red_over_length = m.red_length / m.length; m.length_over_width = m.length / m.width;
662	  return { i: "u" + (k + 1), k, added: true, lines: L, cx: (p + r) / 2, cy: (q + t) / 2, m, x0: 0, y0: 0, h: 0, w: 0, blk: [],
663	    bb: [Math.min(...pts.map((v) => v[0])), Math.min(...pts.map((v) => v[1])), Math.max(...pts.map((v) => v[0])), Math.max(...pts.map((v) => v[1]))] };
664	}
665	const candOf = (i) => (i == null ? null : isAdded(i) ? addedCand(+i.slice(1) - 1) : st.cands[i]);
666	const addedCands = () => st.added.map((_, k) => addedCand(k));
667	// a candidate's one number: the finder's top to bottom, then the added NoRs in the order added
668	const numOf = (c) => (c.added ? st.order.length + c.k + 1 : st.numbers.get(c.i));
669	const nameOf = (c) => "#" + numOf(c);
670	function addedChanged() {
671	  saveAdded(); drawAdded();
672	  if (st.meta) render(); else { renderSelected(); placeRing(); }
673	}
674	function addAdded(x, y) {
675	  st.added.push({ lines: typicalLines(Math.round(x * 10) / 10, Math.round(y * 10) / 10), verdict: null });
676	  st.sel = "u" + st.added.length; addedChanged();
677	}
678	function removeAdded(k) {
679	  const was = st.sel; st.added.splice(k, 1);
680	  if (isAdded(was)) { const j = +was.slice(1) - 1; st.sel = j === k ? null : j > k ? "u" + j : was; }
681	  addedChanged();
682	}
683	function setAdded(k, change) { st.added[k] = { ...st.added[k], ...change }; addedChanged(); }
684	const radiusOf = (c) => Math.max(MISSING_RADIUS, dist(c.lines.length) / 2 + 4);
685	// on the image: the lines, and until the user decides, the circle, glowing
686	function drawAdded() {
687	  const svg = $("#overlay"); svg.querySelector(".added-marks")?.remove();
688	  gtButton();
689	  if (!st.W) return;
690	  svg.setAttribute("viewBox", `0 0 ${st.W} ${st.H}`);
691	  const g = el("g", { class: "added-marks" });
692	  for (const c of addedCands()) {
693	    const v = st.added[c.k].verdict, a = el("g", { "data-i": c.i, class: "added" + (v === "out" ? " out" : "") });
694	    const t = el("text", { x: c.cx + radiusOf(c) + 1, y: c.cy - radiusOf(c) }); t.textContent = numOf(c);
695	    if (!v) a.append(el("circle", { class: "glow", cx: c.cx, cy: c.cy, r: radiusOf(c) }));
696	    const lines = el("g", { class: "lines" });
697	    for (const [k, cls] of [["length", ""], ["width", ""], ["red", "r"]]) {
698	      const [[x1, y1], [x2, y2]] = c.lines[k]; lines.append(el("line", { x1, y1, x2, y2, ...(cls ? { class: cls } : {}) }));
699	    }
700	    a.append(lines, t, el("circle", { class: "hit", cx: c.cx, cy: c.cy, r: radiusOf(c) }));
701	    g.append(a);
702	  }
703	  svg.append(g);
704	  if (st.view === "items" && st.meta) renderList();
705	}
706	// right-clicking the image offers to add a NoR there, or to remove the added one under the pointer
707	{
708	  const menu = $("#ctx");
709	  const close = () => { menu.hidden = true; };
710	  $("#scroller").addEventListener("contextmenu", (e) => {
711	    if (!st.img) return;
712	    const r = $("#base").getBoundingClientRect(), x = (e.clientX - r.left) / st.zoom, y = (e.clientY - r.top) / st.zoom;
713	    if (x < 0 || y < 0 || x > st.W || y > st.H) return;
714	    e.preventDefault();
715	    const k = addedCands().findIndex((c) => Math.hypot(c.cx - x, c.cy - y) <= radiusOf(c));
716	    const b = menu.querySelector("button");
