import { execSync } from "node:child_process";
import { createRequire } from "node:module";
import fs from "node:fs"; import http from "node:http"; import path from "node:path";
const require = createRequire(import.meta.url);
const pw = require(path.join(execSync("npm root -g").toString().trim(), "playwright"));
const [repo, answers, image, out] = process.argv.slice(2);
const STAND_IN = `
const A = await (await fetch("answers/answers.json")).json();
const bin = async (n) => new Uint8Array(await (await fetch("answers/" + n)).arrayBuffer());
let finder;
postMessage({ type: "ready", finders: A.finders, about: A.about, info: { finders: A.finders, about: A.about }, secs: 0 });
onmessage = async ({ data: m }) => {
  if (m.type === "open") { const images = await bin("images.bin"); postMessage({ type: "opened", H: A.H, W: A.W, um: A.um, meta: { H: A.H, W: A.W, um: A.um }, images }, [images.buffer]); }
  else if (m.type === "detect" || (m.type === "call" && m.action === "detect")) {
    finder = m.finder || m.args.finder; const seg = await bin("seg_" + finder + ".bin");
    postMessage(m.type === "detect" ? { type: "detected", meta: A.detected[finder], seg } : { type: "result", action: "detect", meta: A.detected[finder], bytes: seg }, [seg.buffer]);
  } else if (m.type === "refilter") postMessage({ type: "filtered", ...A.filtered[finder][0], seq: m.seq });
  else if (m.type === "call" && m.action === "refilter") postMessage({ type: "result", action: "refilter", meta: A.filtered[finder][0], echo: m.echo });
};`;
const T = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml" };
const server = http.createServer((q, r) => {
  const u = decodeURIComponent(new URL(q.url, "http://x").pathname);
  if (u === "/web/worker.js") { r.writeHead(200, { "content-type": "text/javascript" }); return r.end(STAND_IN); }
  const f = u.startsWith("/web/answers/") ? path.join(answers, u.slice(13)) : path.join(repo, u);
  if (!fs.existsSync(f) || fs.statSync(f).isDirectory()) { r.writeHead(404); return r.end(); }
  r.writeHead(200, { "content-type": T[path.extname(f)] || "application/octet-stream" }); fs.createReadStream(f).pipe(r);
});
await new Promise((ok) => server.listen(0, "[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]", ok));
const origin = `http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:${server.address().port}`;
const browser = await pw.chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1500, height: 900 }, colorScheme: "dark" });
await ctx.route((u) => !u.href.startsWith(origin), (r) => r.abort());
await ctx.addInitScript(() => { delete Navigator.prototype.serviceWorker; localStorage.setItem("nor-seen-version", JSON.stringify("0.11010.30")); });
const page = await ctx.newPage();
page.on("pageerror", (e) => console.error("page error: " + e.message));
await page.goto(origin + "/web/index.html");
await page.waitForFunction(() => document.querySelector("#finder")?.disabled === false);
await page.screenshot({ path: out + "_0ready.png" });
await page.setInputFiles("#file", image);
await page.waitForFunction(() => !document.querySelector("#find").disabled);
await page.evaluate(() => { document.querySelector("#notice").hidden = true; });
await page.click("#find");
await page.waitForFunction(() => st.alone && document.querySelector("#busy").hidden);
await page.click("#sel-next");
await page.waitForTimeout(300);
await page.screenshot({ path: out + "_1image.png" });
await page.click("#switch"); await page.waitForTimeout(300);
await page.screenshot({ path: out + "_2items.png" });
await browser.close(); server.close();
EOF
